@sig trait RetreatReadinessAssessor_Api {
  def id: Art.BridgeId
  def retreatNavigationEvidence_Id : Art.PortId
  def retreatCondition_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var retreatCondition: Frigate_Threat_Response_Coordinator.RetreatCondition.Type = $

  def put_retreatCondition(value : Frigate_Threat_Response_Coordinator.RetreatCondition.Type) : Unit = {
    Contract(
      Modifies(retreatCondition),
      Ensures(
        retreatCondition == value
      )
    )
    Spec {
      retreatCondition = value
    }

    Art.putValue(retreatCondition_Id, Frigate_Threat_Response_Coordinator.RetreatCondition_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class RetreatReadinessAssessor_Initialization_Api (
  val id: Art.BridgeId,
  val retreatNavigationEvidence_Id : Art.PortId,
  val retreatCondition_Id : Art.PortId) extends RetreatReadinessAssessor_Api

@datatype class RetreatReadinessAssessor_Operational_Api (
  val id: Art.BridgeId,
  val retreatNavigationEvidence_Id : Art.PortId,
  val retreatCondition_Id : Art.PortId) extends RetreatReadinessAssessor_Api {

  // Logika spec var representing port state for incoming data port
  @spec var retreatNavigationEvidence: Frigate_Threat_Response_Coordinator.RetreatNavigationEvidence = $

  def get_retreatNavigationEvidence() : Option[Frigate_Threat_Response_Coordinator.RetreatNavigationEvidence] = {
    Contract(
      Ensures(
        Res == Some(retreatNavigationEvidence)
      )
    )
    val value : Option[Frigate_Threat_Response_Coordinator.RetreatNavigationEvidence] = Art.getValue(retreatNavigationEvidence_Id) match {
      case Some(Frigate_Threat_Response_Coordinator.RetreatNavigationEvidence_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port retreatNavigationEvidence.  Expecting 'Frigate_Threat_Response_Coordinator.RetreatNavigationEvidence_Payload' but received ${v}")
        None[Frigate_Threat_Response_Coordinator.RetreatNavigationEvidence]()
      case _ => None[Frigate_Threat_Response_Coordinator.RetreatNavigationEvidence]()
    }
    return value
  }
}
